import { useState, useEffect, useCallback, useRef } from 'react';
import { api } from '../api/client';
import { ApiError } from '../api/types';

export interface ItemFilaOffline {
  localId: string;
  encontroId: string;
  codigo: string;
  lidoEm: string;
  status: 'pendente' | 'sincronizando' | 'concluido' | 'falha-definitiva';
  erro?: string;
  mensagem?: string;
}

const STORAGE_KEY = 'fila-offline-presencas';

export function useFilaOffline(apiClient = api) {
  const [fila, setFila] = useState<ItemFilaOffline[]>(() => {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        return JSON.parse(stored);
      }
    } catch {
      // ignore
    }
    return [];
  });

  const [isOnline, setIsOnline] = useState<boolean>(() => navigator.onLine);
  const isSyncingRef = useRef(false);

  useEffect(() => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(fila));
    } catch {
      // ignore
    }
  }, [fila]);

  const sincronizarProximo = useCallback(async () => {
    if (!navigator.onLine || isSyncingRef.current) {
      return;
    }

    isSyncingRef.current = true;

    try {
      while (true) {
        if (!navigator.onLine) {
          break;
        }

        let targetItem: ItemFilaOffline | undefined;
        setFila((prev) => {
          targetItem = prev.find((item) => item.status === 'pendente');
          if (targetItem) {
            return prev.map((item) =>
              item.localId === targetItem!.localId ? { ...item, status: 'sincronizando' } : item
            );
          }
          return prev;
        });

        if (!targetItem) {
          break;
        }

        try {
          await apiClient.registrarPresenca(targetItem.encontroId, {
            codigo: targetItem.codigo,
            lidoEm: targetItem.lidoEm,
          });

          // Success -> remove from queue
          setFila((prev) => prev.filter((item) => item.localId !== targetItem!.localId));
        } catch (err: any) {
          if (err instanceof ApiError) {
            const businessErrors = ['NAO_INSCRITO', 'CODIGO_INVALIDO', 'FORA_DA_JANELA', 'SINCRONIZACAO_TARDIA'];
            if (businessErrors.includes(err.erro) || (err.status >= 400 && err.status < 500 && err.status !== 408 && err.status !== 429)) {
              let mensagem = err.mensagem;
              if (err.erro === 'NAO_INSCRITO') mensagem = 'Participante não elegível.';
              else if (err.erro === 'CODIGO_INVALIDO') mensagem = 'Código inválido.';
              else if (err.erro === 'FORA_DA_JANELA') mensagem = 'Fora do horário permitido.';

              setFila((prev) =>
                prev.map((item) =>
                  item.localId === targetItem!.localId
                    ? { ...item, status: 'falha-definitiva', erro: err.erro, mensagem }
                    : item
                )
              );
            } else {
              setFila((prev) =>
                prev.map((item) =>
                  item.localId === targetItem!.localId ? { ...item, status: 'pendente' } : item
                )
              );
              break;
            }
          } else {
            setFila((prev) =>
              prev.map((item) =>
                item.localId === targetItem!.localId ? { ...item, status: 'pendente' } : item
              )
            );
            break;
          }
        }
      }
    } finally {
      isSyncingRef.current = false;
    }
  }, [apiClient]);

  useEffect(() => {
    const handleOnline = () => {
      setIsOnline(true);
      sincronizarProximo();
    };
    const handleOffline = () => {
      setIsOnline(false);
    };

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, [sincronizarProximo]);

  const adicionarItem = useCallback((item: Omit<ItemFilaOffline, 'localId'> & { localId?: string }) => {
    const novoItem: ItemFilaOffline = {
      localId: item.localId || `local_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      encontroId: item.encontroId,
      codigo: item.codigo,
      lidoEm: item.lidoEm || new Date().toISOString(),
      status: item.status || 'pendente',
      erro: item.erro,
      mensagem: item.mensagem,
    };

    setFila((prev) => [...prev, novoItem]);

    if (navigator.onLine && novoItem.status === 'pendente') {
      sincronizarProximo();
    }

    return novoItem;
  }, [sincronizarProximo]);

  const removerItem = useCallback((localId: string) => {
    setFila((prev) => prev.filter((item) => item.localId !== localId));
  }, []);

  return {
    fila,
    adicionarItem,
    removerItem,
    sincronizarFila: sincronizarProximo,
    isOnline,
  };
}

import { useState } from 'react';
import { api } from '../api/client';
import { ApiError } from '../api/types';
import { useFilaOffline } from './useFilaOffline';

export function useRegistrarPresenca(encontroId?: string, apiClient = api) {
  const [codigo, setCodigo] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [error, setError] = useState<{ erro: string; mensagem: string } | null>(null);

  const { fila, adicionarItem, removerItem, sincronizarFila, isOnline } = useFilaOffline(apiClient);

  const registrar = async (codigoParam?: string) => {
    const codeToSubmit = codigoParam !== undefined ? codigoParam : codigo;
    if (!encontroId) {
      setError({ erro: 'ENCONTRO_NAO_INFORMADO', mensagem: 'ID do encontro não informado.' });
      return;
    }

    setSubmitting(true);
    setError(null);
    setSuccessMessage(null);

    const lidoEm = new Date().toISOString();

    if (!navigator.onLine) {
      adicionarItem({
        encontroId,
        codigo: codeToSubmit,
        lidoEm,
        status: 'pendente',
      });
      setSubmitting(false);
      setCodigo('');
      setSuccessMessage('Leitura guardada localmente. Pendente de sincronização.');
      return;
    }

    try {
      const result = await apiClient.registrarPresenca(encontroId, { codigo: codeToSubmit, lidoEm });
      setSubmitting(false);
      setCodigo('');

      if (result.status === 201) {
        setSuccessMessage('Presença registrada agora.');
      } else if (result.status === 200) {
        setSuccessMessage('Presença já estava registrada.');
      } else {
        setSuccessMessage('Presença registrada com sucesso.');
      }
    } catch (err: any) {
      setSubmitting(false);
      setCodigo('');

      if (err instanceof ApiError) {
        const businessErrors = ['NAO_INSCRITO', 'CODIGO_INVALIDO', 'FORA_DA_JANELA', 'SINCRONIZACAO_TARDIA'];
        if (businessErrors.includes(err.erro)) {
          let mensagem = err.mensagem;
          if (err.erro === 'NAO_INSCRITO') {
            mensagem = 'Participante não elegível.';
          } else if (err.erro === 'CODIGO_INVALIDO') {
            mensagem = 'Código inválido.';
          } else if (err.erro === 'FORA_DA_JANELA') {
            mensagem = 'Fora do horário permitido.';
          }
          adicionarItem({
            encontroId,
            codigo: codeToSubmit,
            lidoEm,
            status: 'falha-definitiva',
            erro: err.erro,
            mensagem,
          });
          setError({ erro: err.erro, mensagem });
        } else {
          adicionarItem({
            encontroId,
            codigo: codeToSubmit,
            lidoEm,
            status: 'pendente',
          });
          setSuccessMessage('Leitura guardada localmente. Pendente de sincronização.');
        }
      } else {
        adicionarItem({
          encontroId,
          codigo: codeToSubmit,
          lidoEm,
          status: 'pendente',
        });
        setSuccessMessage('Leitura guardada localmente. Pendente de sincronização.');
      }
    }
  };

  return {
    codigo,
    setCodigo,
    submitting,
    successMessage,
    error,
    registrar,
    fila,
    isOnline,
    removerItem,
    sincronizarFila,
  };
}

import React from 'react';
import { useRegistrarPresenca } from '../hooks/useRegistrarPresenca';
import { api } from '../api/client';

interface RegistrarPresencaProps {
  encontroId?: string;
  id?: string;
  apiClient?: typeof api;
}

export function RegistrarPresenca({
  encontroId,
  id,
  apiClient = api,
}: RegistrarPresencaProps) {
  const targetId = encontroId || id;
  const {
    codigo,
    setCodigo,
    submitting,
    successMessage,
    error,
    registrar,
    fila,
    isOnline,
  } = useRegistrarPresenca(targetId, apiClient);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    registrar();
  };

  return (
    <section className="registrar-presenca-container" data-testid="registrar-presenca-container">
      <div className="page-heading">
        <div>
          <span className="eyebrow">Participante</span>
          <h2>Registrar Presença</h2>
          <p>Digite o código do encontro fornecido pela organização para registrar sua presença.</p>
        </div>
        <div className="network-status" data-testid="network-status">
          Status: {isOnline ? <span className="online">Online</span> : <span className="offline">Offline</span>}
        </div>
      </div>

      {successMessage && (
        <div className="success-message" role="status" aria-live="polite" data-testid="success-message">
          {successMessage}
        </div>
      )}

      {error && (
        <div className="error-message" role="alert" data-testid="error-message">
          <strong>Erro ({error.erro}):</strong> <span>{error.mensagem}</span>
        </div>
      )}

      <form onSubmit={handleSubmit} className="form-card">
        <div className="field">
          <label htmlFor="codigo-input">Código do Encontro:</label>
          <input
            id="codigo-input"
            type="text"
            value={codigo}
            onChange={(e) => setCodigo(e.target.value)}
            placeholder="Ex.: K7M2QX"
            required
            disabled={submitting}
            data-testid="codigo-input"
          />
        </div>

        <div className="form-actions">
          <button
            type="submit"
            disabled={submitting || !codigo.trim()}
            className="button button--primary"
            data-testid="submit-button"
          >
            {submitting ? 'Registrando...' : 'Registrar Presença'}
          </button>
        </div>
      </form>

      {fila.length > 0 && (
        <div className="fila-offline-section" data-testid="fila-offline-section">
          <h3>Fila Offline / Pendentes de Sincronização</h3>
          <ul className="fila-lista" data-testid="fila-offline-lista">
            {fila.map((item) => (
              <li key={item.localId} data-testid="fila-item" className={`fila-item status-${item.status}`}>
                <div><strong>Código:</strong> {item.codigo}</div>
                <div><strong>Status:</strong> <span data-testid="item-status">{item.status}</span></div>
                {item.mensagem && (
                  <div className="item-erro" data-testid="item-erro">
                    <strong>Motivo:</strong> {item.mensagem}
                  </div>
                )}
                <div><small>Lido em: {new Date(item.lidoEm).toLocaleTimeString()}</small></div>
              </li>
            ))}
          </ul>
        </div>
      )}
    </section>
  );
}

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import { useFilaOffline } from './useFilaOffline';
import { ApiError } from '../api/types';

describe('useFilaOffline Hook', () => {
  beforeEach(() => {
    localStorage.clear();
    vi.restoreAllMocks();
  });

  afterEach(() => {
    localStorage.clear();
  });

  it('deve salvar item na fila como pendente', () => {
    const { result } = renderHook(() => useFilaOffline());

    act(() => {
      result.current.adicionarItem({
        encontroId: 'enc_1',
        codigo: 'K7M2QX',
        lidoEm: '2026-10-19T10:00:00-03:00',
        status: 'pendente',
      });
    });

    expect(result.current.fila).toHaveLength(1);
    expect(result.current.fila[0]).toMatchObject({
      encontroId: 'enc_1',
      codigo: 'K7M2QX',
      status: 'pendente',
    });

    const stored = JSON.parse(localStorage.getItem('fila-offline-presencas') || '[]');
    expect(stored).toHaveLength(1);
  });

  it('deve persistir e carregar a fila do localStorage entre "recarregamentos"', () => {
    const initialItem = {
      localId: 'loc_123',
      encontroId: 'enc_1',
      codigo: 'K7M2QX',
      lidoEm: '2026-10-19T10:00:00-03:00',
      status: 'pendente' as const,
    };
    localStorage.setItem('fila-offline-presencas', JSON.stringify([initialItem]));

    const { result } = renderHook(() => useFilaOffline());

    expect(result.current.fila).toHaveLength(1);
    expect(result.current.fila[0]).toEqual(initialItem);
  });

  it('deve sincronizar automaticamente itens pendentes quando a rede voltar com sucesso', async () => {
    const registrarPresencaMock = vi.fn().mockResolvedValue({
      presenca: {},
      status: 201,
    });
    const fakeClient = { registrarPresenca: registrarPresencaMock } as any;

    const { result } = renderHook(() => useFilaOffline(fakeClient));

    act(() => {
      result.current.adicionarItem({
        encontroId: 'enc_1',
        codigo: 'K7M2QX',
        lidoEm: '2026-10-19T10:00:00-03:00',
        status: 'pendente',
      });
    });

    await act(async () => {
      window.dispatchEvent(new Event('online'));
    });

    expect(registrarPresencaMock).toHaveBeenCalledWith('enc_1', {
      codigo: 'K7M2QX',
      lidoEm: '2026-10-19T10:00:00-03:00',
    });

    expect(result.current.fila).toHaveLength(0);
  });

  it('deve marcar como falha-definitiva e manter na fila se ocorrer erro de negócio definitivo', async () => {
    const registrarPresencaMock = vi.fn().mockRejectedValue(
      new ApiError(403, 'NAO_INSCRITO', 'Participante não inscrito.')
    );
    const fakeClient = { registrarPresenca: registrarPresencaMock } as any;

    const { result } = renderHook(() => useFilaOffline(fakeClient));

    act(() => {
      result.current.adicionarItem({
        encontroId: 'enc_1',
        codigo: 'K7M2QX',
        lidoEm: '2026-10-19T10:00:00-03:00',
        status: 'pendente',
      });
    });

    await act(async () => {
      await result.current.sincronizarFila();
    });

    expect(result.current.fila).toHaveLength(1);
    expect(result.current.fila[0].status).toBe('falha-definitiva');
    expect(result.current.fila[0].erro).toBe('NAO_INSCRITO');
    expect(result.current.fila[0].mensagem).toBe('Participante não elegível.');
  });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { RegistrarPresenca } from './RegistrarPresenca';
import { api } from '../api/client';
import { ApiError } from '../api/types';

describe('RegistrarPresenca Component', () => {
  beforeEach(() => {
    localStorage.clear();
    vi.restoreAllMocks();
  });

  it('deve registrar presença com sucesso 201 e limpar o campo', async () => {
    const registrarPresencaMock = vi.fn().mockResolvedValue({
      presenca: {
        id: 'pre_1',
        encontroId: 'enc_1',
        participanteId: 'p-carla',
        origem: 'qr',
        lidoEm: '2026-10-19T10:00:00-03:00',
        registradaEm: '2026-10-19T10:00:01-03:00',
        justificativa: null,
      },
      status: 201,
    });

    const fakeClient = {
      ...api,
      registrarPresenca: registrarPresencaMock,
    };

    render(<RegistrarPresenca encontroId="enc_1" apiClient={fakeClient} />);

    const input = screen.getByTestId('codigo-input');
    const submitBtn = screen.getByTestId('submit-button');

    await userEvent.type(input, 'K7M2QX');
    expect(input).toHaveValue('K7M2QX');

    fireEvent.click(submitBtn);

    await waitFor(() => {
      expect(screen.getByTestId('success-message')).toHaveTextContent('Presença registrada agora.');
    });

    expect(registrarPresencaMock).toHaveBeenCalledWith('enc_1', {
      codigo: 'K7M2QX',
      lidoEm: expect.any(String),
    });
    expect(input).toHaveValue('');
  });

  it('deve lidar com sucesso 200 (idempotência - presença já existia) e limpar o campo', async () => {
    const registrarPresencaMock = vi.fn().mockResolvedValue({
      presenca: {
        id: 'pre_1',
        encontroId: 'enc_1',
        participanteId: 'p-carla',
        origem: 'qr',
        lidoEm: '2026-10-19T10:00:00-03:00',
        registradaEm: '2026-10-19T10:00:01-03:00',
        justificativa: null,
      },
      status: 200,
    });

    const fakeClient = {
      ...api,
      registrarPresenca: registrarPresencaMock,
    };

    render(<RegistrarPresenca encontroId="enc_1" apiClient={fakeClient} />);

    const input = screen.getByTestId('codigo-input');
    await userEvent.type(input, 'K7M2QX');
    fireEvent.click(screen.getByTestId('submit-button'));

    await waitFor(() => {
      expect(screen.getByTestId('success-message')).toHaveTextContent('Presença já estava registrada.');
    });

    expect(input).toHaveValue('');
  });

  it('deve tratar erro NAO_INSCRITO, adicionar à fila como falha-definitiva e limpar o campo', async () => {
    const registrarPresencaMock = vi.fn().mockRejectedValue(
      new ApiError(403, 'NAO_INSCRITO', 'Participante não inscrito nesta atividade.')
    );

    const fakeClient = {
      ...api,
      registrarPresenca: registrarPresencaMock,
    };

    render(<RegistrarPresenca encontroId="enc_1" apiClient={fakeClient} />);

    const input = screen.getByTestId('codigo-input');
    await userEvent.type(input, 'K7M2QX');
    fireEvent.click(screen.getByTestId('submit-button'));

    await waitFor(() => {
      const errorEl = screen.getByTestId('error-message');
      expect(errorEl).toBeInTheDocument();
      expect(errorEl).toHaveTextContent('NAO_INSCRITO');
      expect(errorEl).toHaveTextContent('Participante não elegível.');
    });

    expect(screen.getByTestId('fila-offline-section')).toBeInTheDocument();
    expect(screen.getByTestId('item-status')).toHaveTextContent('falha-definitiva');
    expect(screen.getByTestId('item-erro')).toHaveTextContent('Participante não elegível.');
    expect(input).toHaveValue('');
  });

  it('deve tratar erro CODIGO_INVALIDO e limpar o campo', async () => {
    const registrarPresencaMock = vi.fn().mockRejectedValue(
      new ApiError(422, 'CODIGO_INVALIDO', 'Código incorreto.')
    );

    const fakeClient = {
      ...api,
      registrarPresenca: registrarPresencaMock,
    };

    render(<RegistrarPresenca encontroId="enc_1" apiClient={fakeClient} />);

    const input = screen.getByTestId('codigo-input');
    await userEvent.type(input, 'WRONG1');
    fireEvent.click(screen.getByTestId('submit-button'));

    await waitFor(() => {
      const errorEl = screen.getByTestId('error-message');
      expect(errorEl).toBeInTheDocument();
      expect(errorEl).toHaveTextContent('CODIGO_INVALIDO');
      expect(errorEl).toHaveTextContent('Código inválido.');
    });

    expect(input).toHaveValue('');
  });

  it('deve tratar erro FORA_DA_JANELA e limpar o campo', async () => {
    const registrarPresencaMock = vi.fn().mockRejectedValue(
      new ApiError(422, 'FORA_DA_JANELA', 'Fora do horário.')
    );

    const fakeClient = {
      ...api,
      registrarPresenca: registrarPresencaMock,
    };

    render(<RegistrarPresenca encontroId="enc_1" apiClient={fakeClient} />);

    const input = screen.getByTestId('codigo-input');
    await userEvent.type(input, 'K7M2QX');
    fireEvent.click(screen.getByTestId('submit-button'));

    await waitFor(() => {
      const errorEl = screen.getByTestId('error-message');
      expect(errorEl).toBeInTheDocument();
      expect(errorEl).toHaveTextContent('FORA_DA_JANELA');
      expect(errorEl).toHaveTextContent('Fora do horário permitido.');
    });

    expect(input).toHaveValue('');
  });

  it('deve tratar erro de rede / sem conexão guardando localmente e limpando o campo', async () => {
    const registrarPresencaMock = vi.fn().mockRejectedValue(
      new Error('Failed to fetch')
    );

    const fakeClient = {
      ...api,
      registrarPresenca: registrarPresencaMock,
    };

    render(<RegistrarPresenca encontroId="enc_1" apiClient={fakeClient} />);

    const input = screen.getByTestId('codigo-input');
    await userEvent.type(input, 'K7M2QX');
    fireEvent.click(screen.getByTestId('submit-button'));

    await waitFor(() => {
      const successEl = screen.getByTestId('success-message');
      expect(successEl).toBeInTheDocument();
      expect(successEl).toHaveTextContent('Leitura guardada localmente. Pendente de sincronização.');
    });

    expect(screen.getByTestId('fila-offline-section')).toBeInTheDocument();
    expect(screen.getByTestId('item-status')).toHaveTextContent('pendente');
    expect(input).toHaveValue('');
  });
});

